// Generated by vibelang from src/features/code-intel/metrics.ts; the migrate flow writes it again with each batch.
import { Metric } from "effect";
// Usage metrics for code intelligence, exported over OTLP with the rest of the browser's telemetry
// (docs/observability.md#browser). Labels carry what a person did and how it ended, never a path, a symbol or text. The
// language server's own requests are counted by `@smthrs/platform-browser`'s `BrowserLanguageServer`.
/**
 * What a person asked of the code, by `act` (`hover`, `definition`, `references`, `problems`, `outline`) and `outcome`
 * (`answered`, `none` when there was nothing to show, or `failed`).
 */
export const asks = Metric.counter("smithers_web_code_intel_asks", {
    description: "What a person asked of the code view's language server, by act and outcome",
    incremental: true,
});
/** Language servers this tab started, one per repository and commit. */
export const sessions = Metric.counter("smithers_web_code_intel_sessions", {
    description: "Browser language servers a tab started, one per repository and commit",
    incremental: true,
});
